import axios from 'axios';
import cache from 'src/utils/cache';
import { defineComponent, ref } from 'vue';
import { type dynamicObj } from 'src/pages/assets';
import docTypeLable from 'src/utils/docTypeLable';
import { api, getAuthorizationToken } from 'pages/APIs';
import { useDocAttributesStore, useDashboardStore } from 'src/store/main';
import { addOrgIdQueryString } from 'src/utils/organization/org_id_helper';
import {
  validationScreenStatuses,
  approve_before_export_v2,
  CONSTANTS,
  status_to_skip_update,
} from 'src/constants';

export default defineComponent({
  mixins: [docTypeLable, cache],
  data() {
    return {
      docrowID: ref(),
      statusList: [] as any,
      QualityText: ref(),
      QualityConfirm: ref(false),
    };
  },
  methods: {
    prepareStatusList() {
      this.statusList['new'] = [];
      this.statusList['new']['value'] = 'new';
      this.statusList['new']['class'] = 'bg-light-green-6 bg-green-2B9D73';

      this.statusList['ready_for_review'] = [];
      this.statusList['ready_for_review']['value'] = 'ready_for_review';
      this.statusList['ready_for_review']['class'] =
        'bg-amber-7 bg-yellow-F9A929';

      this.statusList['ready_for_validation'] = [];
      this.statusList['ready_for_validation']['value'] = 'ready_for_validation';
      this.statusList['ready_for_validation']['class'] =
        'bg-amber-7 bg-yellow-F9A929';

      this.statusList['validating'] = [];
      this.statusList['validating']['value'] = 'ready_for_validation';
      this.statusList['validating']['class'] = 'bg-amber-7 bg-yellow-F9A929';

      this.statusList['validated_pending_export'] = [];
      this.statusList['validated_pending_export']['value'] =
        'validated_pending_export';
      this.statusList['validated_pending_export']['class'] =
        'bg-amber-7 bg-yellow-F9A929';

      this.statusList['pending_confirmation'] = [];
      this.statusList['pending_confirmation']['value'] = 'pending_confirmation';
      this.statusList['pending_confirmation']['class'] =
        'bg-amber-7 bg-yellow-F9A929';

      this.statusList['finished'] = [];
      this.statusList['finished']['value'] = 'finished';
      this.statusList['finished']['class'] = 'bg-light-green-6 bg-green-2B9D73';

      this.statusList['workflow'] = [];
      this.statusList['workflow']['value'] = 'workflow';
      this.statusList['workflow']['class'] = 'bg-light-green-6 bg-green-2B9D73';

      this.statusList['completed'] = [];
      this.statusList['completed']['value'] = 'completed';
      this.statusList['completed']['class'] =
        'bg-light-green-6 bg-green-2B9D73';

      this.statusList['restarted'] = [];
      this.statusList['restarted']['value'] = 'restarted';
      this.statusList['restarted']['class'] = 'bg-blue-14';

      this.statusList['error'] = [];
      this.statusList['error']['value'] = 'error';
      this.statusList['error']['class'] = 'bg-red-13 bg-red-D00000';

      this.statusList['export_error'] = [];
      this.statusList['export_error']['value'] = 'error';
      this.statusList['export_error']['class'] = 'bg-red-13 bg-red-D00000';

      this.statusList['restart_export'] = [];
      this.statusList['restart_export']['value'] = 'restart_export';
      this.statusList['restart_export']['class'] = 'bg-blue-14';

      this.statusList['running'] = [];
      this.statusList['running']['value'] = 'running';
      this.statusList['running']['class'] = 'bg-blue-14';

      this.statusList['in_progress'] = [];
      this.statusList['in_progress']['value'] = 'in_progress';
      this.statusList['in_progress']['class'] = 'bg-blue-14';

      this.statusList['restart_in_progress'] = [];
      this.statusList['restart_in_progress']['value'] = 'restart_in_progress';
      this.statusList['restart_in_progress']['class'] = 'bg-blue-14';

      this.statusList['exporting'] = [];
      this.statusList['exporting']['value'] = 'exporting';
      this.statusList['exporting']['class'] = 'bg-blue-14';

      this.statusList['archived'] = [];
      this.statusList['archived']['value'] = 'archived';
      this.statusList['archived']['class'] = 'bg-blue-14';

      this.statusList['pending_vertex_verification'] = [];
      this.statusList['pending_vertex_verification']['value'] = 'pending_vertex_verification';
      this.statusList['pending_vertex_verification']['class'] = 'bg-blue-14';

      this.statusList['vertex_tax_rejected'] = [];
      this.statusList['vertex_tax_rejected']['value'] = 'vertex_tax_rejected';
      this.statusList['vertex_tax_rejected']['class'] = 'bg-red-13 bg-red-D00000';

      this.statusList['vertex_invoice_verification'] = [];
      this.statusList['vertex_invoice_verification']['value'] = 'vertex_invoice_verification';
      this.statusList['vertex_invoice_verification']['class'] = 'bg-blue-14';

      this.statusList['pending_erp_approval'] = [];
      this.statusList['pending_erp_approval']['value'] = 'pending_erp_approval';
      this.statusList['pending_erp_approval']['class'] = 'bg-blue-14';
    },
    setDisplayDocType(row: any) {
      const type = this.getDocTypeForDisplay(row);
      const label = this.displayDocType(type);
      return String(label);
    },
    getStatusClass(status: string) {
      let status_class = '';
      const status_exists = this.statusList.hasOwnProperty(status);
      if (status_exists) {
        status_class = this.statusList[status]['class'];
      } else {
        status_class = 'bg-grey bg-grey-949494';
      }
      status_class += ' dashboard-status-badge';
      return status_class;
    },
    setRowStyle(row: any) {
      if (
        row.hasOwnProperty('export_data_fetched') &&
        row['export_data_fetched'] === true &&
        !this.isStatusError(row['status'])
      ) {
        return 'exported-row';
      }
    },
    getClassesForColumn(status: string, column_name: string) {
      let styleClass = '';
      const styleClass2 = '';

      let styleClass1 =
        status === 'running' ? 'enableDrawingRectangle' : 'cursor-pointer';

      styleClass1 += column_name === 'filename' ? ' text-primary ' : '';
      styleClass1 += column_name.includes('amount') ? ' text-right ' : '';
      // if (column_name === 'status') {
      //   if (this.statusList.hasOwnProperty(status)) {
      //     styleClass2 = status ? this.statusList[status].class : '';
      //   }
      // }
      return (styleClass = styleClass1 + ' ' + styleClass2);
    },
    rowClick(row: dynamicObj, cacheRow: boolean, isMediUser: boolean) {
      const id = row['id'] ? row['id'] : row['doc_id'];
      row['id'] = id;
      const status = row['status'];
      const type = row['doc_type'];

      if (cacheRow) {
        this.storeCurrentRowId(id);
      }

      if (status === 'archived') {
        this.toValidationScreen(id);
        return;
      }

      if (status === 'vertex_tax_rejected') {
        this.toVertexDetailsScreen(id);
        return;
      }

      if (this.isStatusError(status)) {
        this.toDocumentErrorView(row);
        return;
      }

      if (status === 'classified') {
        this.toDocumentClassifiyView(row);
        return;
      }

      if (status === 'validating' || status === 'validated_pending_export') {
        return;
      }

      if (status === 'pending_confirmation') {
        this.getQualityInfos(row);
        return;
      }

      if (status === 'validated_pending_approval') {
        this.toPendingApprovalScreen(id, row);
        return;
      }

      if (status === 'approved_pending_second_approval') {
        this.toPendingSecondApprovalScreen(id, row);
        return;
      }

      if (status === 'in_review') {
        this.toInReviewScreen(id, row);
        return;
      }

      if (status === 'rejected') {
        this.toRejectedScreen(id);
        return;
      }

      if (!validationScreenStatuses.includes(status)) {
        return;
      }

      if (isMediUser) {
        this.handleMediRoutes(row);
        return;
      }

      // Every status left here is in validationScreenStatuses, and the
      // validation screen decides editability itself (handleReadOnly() in
      // field-validation-view.vue: readOnlyDocStatus + ACL + doc lock).
      this.toValidationScreen(id);
    },
    storeCurrentRowId(rowId: string) {
      this.setDataToSessionStorage('selected_row_id', rowId);
    },
    isStatusError(status: string) {
      return status === 'error' || status === 'export_error';
    },
    toRejectedScreen(doc_id: string) {
      this.$router.push('/rejected/' + doc_id);
    },
    toVertexDetailsScreen(doc_id: string) {
      this.$router.push('/vertex-details/' + doc_id);
    },

    toFlowScreen(doc_id: string) {
      this.storeCurrentRowId(doc_id);
      this.$router.push('/doc_flow/' + doc_id);
    },
    toValidationScreen(doc_id: string) {
      this.$router.push('/field_validation_v1/' + doc_id);
    },

    async toInReviewScreen(doc_id: string, row: any) {
      const doc_attribute_store = useDocAttributesStore();
      const isApprovalV2 =
        await doc_attribute_store.getSettingsByDocTypeAndSettingKey(
          row.doc_type,
          approve_before_export_v2,
        );

      if (isApprovalV2) {
        this.$router.push('/in-review-v2/' + doc_id);
      } else {
        this.$router.push('/in_review/' + doc_id);
      }
    },

    async toPendingApprovalScreen(doc_id: string, row: any) {
      const doc_attribute_store = useDocAttributesStore();
      const isApprovalV2 =
        await doc_attribute_store.getSettingsByDocTypeAndSettingKey(
          row.doc_type,
          approve_before_export_v2,
        );

      if (isApprovalV2) {
        this.$router.push('/ready_for_approval_v3/' + doc_id);
      } else {
        this.$router.push('/ready-for-approval-v2/' + doc_id);
      }
    },
    async toPendingSecondApprovalScreen(doc_id: string, row: any) {
      const doc_attribute_store = useDocAttributesStore();
      const isApprovalV2 =
        await doc_attribute_store.getSettingsByDocTypeAndSettingKey(
          row.doc_type,
          approve_before_export_v2,
        );

      if (isApprovalV2) {
        this.$router.push('/ready-for-second-approval-v3/' + doc_id);
      } else {
        this.$router.push('/ready-for-second-approval-v2/' + doc_id);
      }
    },
    toMediValidationScreen(doc_id: string) {
      this.$router.push('/field_validation/' + doc_id);
    },

    toMediValidationV3Screen(doc_id: string) {
      this.$router.push('/medi_order_v3/' + doc_id);
    },

    toDocumentErrorView(row: dynamicObj) {
      this.$router.push('/document_error/' + row['id']);
    },

    toDocumentClassifiyView(row: dynamicObj) {
      this.$router.push('/document_classifiy/' + row['id']);
    },
    handleMediRoutes(row: any) {
      this.toMediValidationV3Screen(row['id']);
    },
    async getQualityInfos(row: any) {
      if (row['status'] == 'pending_confirmation') {
        const token: string = await getAuthorizationToken();

        const resp = await axios.get(addOrgIdQueryString(api.get_error_infos), {
          headers: {
            Authorization: token,
          },
          params: {
            doc_id: row['id'],
          },
        });
        resp['data']['row'] = row;
        if (Object.keys(resp).length === 1) {
          this.QualityText = { message: 'None' };
          return false;
        } else {
          this.QualityText = resp['data'];
          this.QualityConfirm = true;
          this.docrowID = resp['data']['row']['id'];
          return true;
        }
      }
    },

    updateDashboardTable(newData: any, oldData: any) {
      // Find the document in the array
      const index = oldData.findIndex(
        (entry: dynamicObj) => entry.id === newData.doc_id,
      );

      // Early return if document not found
      if (index === -1) return;

      // Set notifyUpdate flag if status should trigger update
      if (!status_to_skip_update.includes(newData.status)) {
        const dashboard_store = useDashboardStore();
        dashboard_store.notifyUpdate = true;
      }

      // Create merged record with spread operator (preserves old data, overlays new data)
      const updatedRecord = {
        ...oldData[index],
        ...newData,
      };

      // Map doc_id to id field (WebSocket sends doc_id but table uses id)
      updatedRecord.id = newData.doc_id;

      // WS updates send the raw status and a separate pending_workflow_execution
      // flag (the REST dashboard masks server-side, the WS path leaves it to the
      // client — doc2api commit 384886c2555); re-apply the mask so the row shows
      // "Workflow In Progress" instead of the underlying status.
      if (updatedRecord.pending_workflow_execution) {
        updatedRecord.status = CONSTANTS.pending_workflow_execution;
      }

      // Use splice to trigger Vue reactivity (replaces array element)
      oldData.splice(index, 1, updatedRecord);
    },
  },
});
